@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@500;600&family=Noto+Sans+SC:wght@400;500;700;900&family=Space+Grotesk:wght@500;600;700&display=swap");

:root {
  --font-ui: "Noto Sans SC", "PingFang SC", "Microsoft YaHei", sans-serif;
  --font-accent: "IBM Plex Mono", "Space Grotesk", monospace;
  --font-display: "Space Grotesk", "Noto Sans SC", sans-serif;
}

/* Report records final compact layout: one-screen historical data workspace. */
.content.is-subpage-compact .report-record-page,
.report-record-page {
  --report-record-panel-border: rgba(103, 189, 245, 0.3);
  --report-record-panel-border-soft: rgba(103, 189, 245, 0.17);
  --report-record-panel-bg: rgba(8, 23, 37, 0.86);
  --report-record-panel-bg-strong: rgba(10, 31, 49, 0.9);
  --report-record-control-bg: rgba(6, 20, 33, 0.72);
  --report-record-accent: rgba(95, 202, 255, 0.94);
  --report-record-good: rgba(83, 226, 139, 0.94);
  --report-record-warn: rgba(255, 201, 94, 0.95);
  display: grid !important;
  grid-template-rows: 136px 54px minmax(238px, 1fr) 226px;
  gap: 8px !important;
  height: calc(100dvh - 82px);
  min-height: 0;
  overflow: hidden;
}

.content.is-subpage-compact .report-record-header.subpage-command-board,
.report-record-header.subpage-command-board {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) minmax(430px, 520px) !important;
  grid-template-rows: 50px 64px;
  align-items: stretch !important;
  gap: 8px 10px !important;
  min-height: 0;
  padding: 8px 10px !important;
  border-radius: 8px !important;
  overflow: visible !important;
}

.content.is-subpage-compact .report-record-command-copy,
.report-record-command-copy {
  display: grid;
  align-content: center;
  gap: 2px;
  min-width: 0;
}

.content.is-subpage-compact .report-record-command-copy h2,
.report-record-command-copy h2 {
  font-size: clamp(24px, 1.75vw, 28px) !important;
  line-height: 1.08 !important;
}

.content.is-subpage-compact .report-record-command-side,
.report-record-command-side {
  display: grid !important;
  grid-template-rows: 1fr auto;
  gap: 5px;
  min-width: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.report-record-command-state {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  min-width: 0;
}

.report-record-command-state article {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 4px;
  padding: 7px 9px;
  border: 1px solid var(--report-record-panel-border-soft);
  border-radius: 7px;
  background: rgba(9, 30, 48, 0.76);
}

.report-record-command-state span,
.report-record-metric-strip span,
.report-record-side-title span,
.report-record-side-head span,
.report-record-trace-grid span,
.report-record-table-toolbar span,
.report-record-table-footer span {
  color: rgba(166, 194, 213, 0.88);
  font-size: 12px !important;
  line-height: 1.2 !important;
}

.report-record-command-state strong {
  min-width: 0;
  overflow: hidden;
  color: rgba(238, 248, 255, 0.98);
  font-size: 14px !important;
  line-height: 1.2 !important;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.report-record-command-state article:first-child strong {
  color: var(--report-record-good);
}

.content.is-subpage-compact .report-record-status-list,
.report-record-status-list {
  display: flex;
  justify-content: flex-end;
  gap: 5px;
  min-width: 0;
  overflow: hidden;
}

.content.is-subpage-compact .report-record-status-chip,
.report-record-status-chip {
  flex: 0 1 auto;
  min-height: 20px !important;
  padding: 2px 7px !important;
  border-radius: 999px !important;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.content.is-subpage-compact .report-record-header-filter,
.report-record-header-filter {
  grid-column: 1 / -1;
  min-width: 0;
}

.content.is-subpage-compact .report-record-filter-grid,
.report-record-filter-grid {
  display: grid !important;
  grid-template-columns: 1fr 1fr 0.78fr 1fr 1fr 270px !important;
  gap: 7px !important;
  min-width: 0;
}

.content.is-subpage-compact .report-record-field,
.report-record-field {
  display: grid !important;
  gap: 3px !important;
  min-width: 0;
  height: 48px;
  padding: 6px 9px !important;
  border: 1px solid var(--report-record-panel-border-soft) !important;
  border-radius: 7px !important;
  background: var(--report-record-control-bg) !important;
}

.content.is-subpage-compact .report-record-field input,
.report-record-field input,
.content.is-subpage-compact .report-record-select-trigger,
.report-record-select-trigger {
  height: 23px !important;
  min-height: 23px !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: rgba(240, 248, 255, 0.98) !important;
  font-size: 14px !important;
  line-height: 23px !important;
}

.content.is-subpage-compact .report-record-select-trigger,
.report-record-select-trigger {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  width: 100%;
}

.content.is-subpage-compact .report-record-actions-inline,
.report-record-actions-inline {
  display: grid !important;
  grid-template-columns: 1fr 0.85fr 1.1fr;
  align-items: end;
  gap: 7px !important;
  min-width: 0;
}

.content.is-subpage-compact .report-record-actions-inline .report-record-button,
.report-record-actions-inline .report-record-button {
  height: 38px !important;
  min-height: 38px !important;
  border-radius: 7px !important;
  font-size: 14px !important;
  line-height: 1 !important;
  white-space: nowrap;
}

.report-record-metric-strip {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 8px;
  min-height: 0;
  padding: 7px;
  border: 1px solid var(--report-record-panel-border);
  border-radius: 8px;
  background: var(--report-record-panel-bg);
}

.report-record-metric-strip article {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 9px;
  border: 1px solid var(--report-record-panel-border-soft);
  border-radius: 7px;
  background: rgba(9, 30, 48, 0.7);
}

.report-record-metric-strip strong {
  min-width: 0;
  overflow: hidden;
  color: rgba(241, 249, 255, 0.98);
  font-size: 18px !important;
  line-height: 1.1 !important;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.report-record-metric-strip article.is-good strong {
  color: var(--report-record-good);
}

.report-record-metric-strip article.is-warn strong {
  color: var(--report-record-warn);
}

.report-record-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.72fr) minmax(350px, 0.78fr);
  gap: 8px;
  min-height: 0;
  padding: 8px;
  border: 1px solid var(--report-record-panel-border);
  border-radius: 8px;
  background: var(--report-record-panel-bg);
  overflow: hidden;
}

.report-record-chart-panel,
.report-record-side-panel,
.report-record-table-panel {
  min-width: 0;
  min-height: 0;
  border: 1px solid var(--report-record-panel-border-soft);
  border-radius: 8px;
  background: rgba(6, 20, 33, 0.66);
  overflow: hidden;
}

.report-record-chart-panel {
  display: grid;
}

.report-record-chart-panel .report-record-chart-card {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: 38px minmax(0, 1fr) 24px;
  padding: 0 !important;
  border: 0;
  background: transparent;
  overflow: hidden;
}

.report-record-chart-panel .report-record-chart-head {
  min-height: 0;
  padding: 6px 10px !important;
  border-bottom: 1px solid rgba(103, 189, 245, 0.14);
}

.report-record-chart-panel .report-record-chart-head p {
  margin: 0 !important;
  color: rgba(166, 194, 213, 0.86);
  font-size: 12px !important;
  line-height: 1.2 !important;
}

.report-record-chart-panel .report-record-chart-plot-frame {
  grid-template-columns: 58px minmax(0, 1fr) !important;
  gap: 8px !important;
  min-height: 0;
  padding: 4px 10px 0 6px;
  overflow: hidden !important;
}

.report-record-chart-panel .report-record-chart-axis {
  margin-left: 72px !important;
  padding: 0 10px 7px 0;
}

.report-record-side-panel {
  display: grid;
  grid-template-rows: 32px minmax(88px, 0.9fr) minmax(58px, 0.62fr) 40px;
  gap: 5px;
  padding: 7px;
}

.report-record-side-head,
.report-record-side-title,
.report-record-table-toolbar,
.report-record-table-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.report-record-side-head strong,
.report-record-side-title strong,
.report-record-table-toolbar strong {
  min-width: 0;
  overflow: hidden;
  color: rgba(241, 249, 255, 0.98);
  font-size: 15px !important;
  line-height: 1.2 !important;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.report-record-side-block {
  min-height: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 5px;
  padding: 6px;
  border: 1px solid rgba(103, 189, 245, 0.14);
  border-radius: 7px;
  background: rgba(11, 31, 50, 0.55);
  overflow: hidden;
}

.report-record-side-block.is-point-picker {
  grid-template-rows: auto auto minmax(0, 1fr);
}

.report-record-side-panel .report-record-selection-tree,
.report-record-side-panel .report-record-reg-grid {
  min-height: 0 !important;
  overflow: auto !important;
  scrollbar-color: rgba(105, 172, 220, 0.28) transparent;
}

.report-record-side-panel .report-record-selection-tree {
  gap: 3px !important;
}

.report-record-selection-tree.is-compact .report-record-selection-tree-type > summary,
.report-record-selection-tree.is-compact .report-record-selection-tree-device > summary {
  min-height: 24px;
  border-radius: 6px;
}

.report-record-selection-tree.is-compact .report-record-selection-tree-point {
  min-height: 20px;
  border-radius: 6px;
}

.report-record-side-panel .report-record-reg-selection-actions {
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 6px !important;
}

.report-record-side-panel .report-record-reg-selection-actions .report-record-button {
  height: 26px !important;
  min-height: 26px !important;
  min-width: 72px !important;
  padding: 0 10px !important;
  border-radius: 999px !important;
  font-size: 12px !important;
  line-height: 26px !important;
}

.report-record-side-panel .report-record-reg-grid,
.content.is-subpage-compact .report-record-side-panel .report-record-reg-grid {
  display: flex !important;
  flex-wrap: wrap !important;
  align-content: flex-start !important;
  gap: 4px !important;
}

.report-record-side-panel .report-record-reg-chip,
.content.is-subpage-compact .report-record-side-panel .report-record-reg-chip {
  width: auto !important;
  max-width: 170px !important;
  min-height: 22px !important;
  padding: 2px 7px !important;
  border-radius: 999px !important;
  font-size: 11.5px !important;
  line-height: 1.2 !important;
}

.report-record-trace-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px;
  min-height: 0;
}

.report-record-trace-grid article {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 2px;
  padding: 4px 6px;
  border: 1px solid rgba(103, 189, 245, 0.14);
  border-radius: 7px;
  background: rgba(13, 35, 57, 0.62);
}

.report-record-trace-grid strong {
  min-width: 0;
  overflow: hidden;
  color: rgba(240, 248, 255, 0.98);
  font-size: 11.5px !important;
  line-height: 1.16 !important;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.report-record-trace-grid article:first-child strong {
  color: var(--report-record-good);
}

.report-record-table-panel {
  display: grid;
  grid-template-rows: 38px minmax(0, 1fr) 34px;
  padding: 0;
}

.report-record-table-toolbar {
  min-height: 0;
  padding: 6px 10px;
  border-bottom: 1px solid rgba(103, 189, 245, 0.14);
}

.report-record-table-status {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
}

.report-record-table-status span {
  max-width: 360px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.report-record-table-status span.is-good {
  color: var(--report-record-good);
}

.report-record-table-status span.is-warn {
  color: var(--report-record-warn);
}

.content.is-subpage-compact .report-record-page .report-record-table-shell,
.report-record-page .report-record-table-shell {
  min-height: 0;
  overflow: auto !important;
}

.content.is-subpage-compact .report-record-page .report-record-table,
.report-record-page .report-record-table {
  min-width: 1040px !important;
  border-spacing: 0 !important;
}

.content.is-subpage-compact .report-record-page .report-record-table thead th,
.report-record-page .report-record-table thead th,
.content.is-subpage-compact .report-record-page .report-record-table tbody td,
.report-record-page .report-record-table tbody td {
  height: 28px !important;
  padding: 4px 10px !important;
  font-size: 12.5px !important;
  line-height: 1.18 !important;
}

.content.is-subpage-compact .report-record-page .report-record-table thead th,
.report-record-page .report-record-table thead th {
  padding-top: 4px !important;
  padding-bottom: 4px !important;
  background: rgba(13, 38, 60, 0.76) !important;
}

.report-record-table-footer {
  min-height: 0;
  padding: 5px 10px;
  border-top: 1px solid rgba(103, 189, 245, 0.14);
}

.report-record-empty-row td,
.content.is-subpage-compact .report-record-page .report-record-empty-row td {
  height: 72px !important;
  color: rgba(180, 207, 225, 0.78);
  text-align: center !important;
}

.report-record-pagination {
  display: flex;
  align-items: center;
  gap: 8px;
}

.report-record-pagination strong {
  color: rgba(226, 239, 248, 0.96);
  font-size: 12px !important;
  line-height: 1;
}

.content.is-subpage-compact .report-record-page .report-record-pagination button,
.report-record-page .report-record-pagination button {
  height: 24px !important;
  min-height: 24px !important;
  padding: 0 8px !important;
  border-radius: 5px !important;
  font-size: 12px !important;
  line-height: 22px !important;
}

.report-record-empty.is-compact {
  min-height: 0;
  padding: 8px;
  border-radius: 7px;
  background: rgba(7, 20, 33, 0.44);
}

@media (max-width: 1320px) {
  .content.is-subpage-compact .report-record-page,
  .report-record-page {
    height: auto;
    overflow: visible;
  }

  .content.is-subpage-compact .report-record-header.subpage-command-board,
  .report-record-header.subpage-command-board,
  .report-record-workspace {
    grid-template-columns: 1fr !important;
  }

  .content.is-subpage-compact .report-record-filter-grid,
  .report-record-filter-grid,
  .report-record-metric-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .report-record-side-panel {
    min-height: 360px;
  }
}

/* UI polish overrides for environment + cold log pages */
.environment-compat-header,
.cold-log-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: flex-start;
}

.environment-compat-header p,
.cold-log-header p {
  margin: 0;
  max-width: 760px;
}

.cold-log-header p {
  line-height: 1.6;
}

.environment-compat-main {
  display: grid;
  grid-template-columns: minmax(300px, 0.9fr) minmax(0, 1.1fr);
  gap: 14px;
  align-items: start;
}

@media (max-width: 1100px) {
  .environment-compat-main {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .environment-compat-header,
  .cold-log-header {
    grid-template-columns: 1fr;
  }
}

/* Late overrides for refreshed project switch shell */
.project-switch-page {
  gap: 10px;
}

.project-switch-header.subpage-command-board {
  gap: 12px 14px;
}

.project-switch-command-copy {
  gap: 8px;
}

.project-switch-command-eyebrow {
  margin: 0;
  color: rgba(137, 214, 255, 0.78);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.project-switch-command-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.project-switch-command-tags span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid rgba(109, 191, 255, 0.16);
  background:
    linear-gradient(180deg, rgba(18, 40, 64, 0.62), rgba(10, 21, 36, 0.58)),
    radial-gradient(circle at top left, rgba(96, 218, 255, 0.12), transparent 62%);
  color: var(--text-2);
  backdrop-filter: blur(10px);
}

.project-switch-command-tags strong {
  color: rgba(191, 222, 244, 0.72);
  font-size: 11px;
  font-weight: 600;
}

.project-switch-command-tags em {
  color: var(--text-1);
  font-style: normal;
  font-size: 12px;
}

.project-switch-command-side {
  min-width: min(320px, 100%);
  gap: 10px;
}

.project-switch-command-note strong {
  display: block;
  color: var(--text-1);
  font-size: 18px;
  line-height: 1.24;
}

.project-switch-command-note p {
  margin: 4px 0 0;
  color: rgba(186, 214, 235, 0.84);
  font-size: 12px;
  line-height: 1.55;
}

.project-switch-command-lines {
  display: grid;
  gap: 8px;
}

.project-switch-command-lines span {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 0 12px;
  border-radius: 12px;
  border: 1px solid rgba(109, 191, 255, 0.14);
  background: rgba(10, 24, 40, 0.52);
  color: rgba(194, 217, 234, 0.9);
  font-size: 12px;
}

.project-switch-workspace-stage {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px 16px;
  align-items: end;
  padding: 16px 18px;
  border-radius: 22px;
  border: 1px solid rgba(116, 188, 255, 0.16);
  background:
    linear-gradient(135deg, rgba(12, 31, 50, 0.94), rgba(8, 19, 32, 0.9)),
    radial-gradient(circle at top left, rgba(104, 218, 255, 0.11), transparent 54%);
  box-shadow: 0 16px 30px rgba(5, 16, 28, 0.16);
  overflow: hidden;
}

.project-switch-workspace-stage::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(150, 221, 255, 0.05), transparent 26%);
  pointer-events: none;
}

.project-switch-workspace-stage-copy {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 6px;
}

.project-switch-workspace-stage-copy strong {
  color: var(--text-1);
  font-size: clamp(20px, 2vw, 28px);
  line-height: 1.08;
  letter-spacing: -0.03em;
}

.project-switch-workspace-stage-copy p {
  margin: 0;
  max-width: 760px;
  color: rgba(188, 214, 234, 0.86);
  font-size: 12px;
  line-height: 1.6;
}

.project-switch-workspace-stage-meta {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.project-switch-workspace-stage-meta span {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid rgba(115, 190, 255, 0.16);
  background: rgba(9, 23, 38, 0.58);
  color: rgba(198, 218, 234, 0.92);
  font-size: 12px;
}

.project-switch-queue-shell {
  display: grid;
  gap: 12px;
  padding: 16px 18px 18px;
  border-radius: 24px;
  border: 1px solid rgba(115, 188, 255, 0.14);
  background:
    linear-gradient(180deg, rgba(12, 28, 45, 0.9), rgba(9, 18, 30, 0.88)),
    radial-gradient(circle at top left, rgba(94, 214, 255, 0.08), transparent 44%);
  box-shadow: 0 16px 32px rgba(5, 16, 28, 0.12);
}

.project-switch-queue-head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: end;
}

.project-switch-queue-head span {
  display: block;
  margin-bottom: 6px;
  color: rgba(156, 197, 225, 0.74);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.project-switch-queue-head strong {
  color: var(--text-1);
  font-size: 18px;
  line-height: 1.25;
}

.project-switch-queue-head p {
  margin: 0;
  max-width: 420px;
  color: rgba(186, 214, 234, 0.82);
  font-size: 12px;
  line-height: 1.55;
}

.project-switch-grid {
  width: 100%;
  max-width: none;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
}

.project-switch-card {
  position: relative;
  gap: 14px;
  padding: 16px;
  min-height: 100%;
  border-color: rgba(114, 188, 255, 0.14);
  background:
