  background: rgba(255, 255, 255, 0.03);
}

.energy-analysis-legend-item strong {
  display: block;
  margin-bottom: 3px;
}

.energy-analysis-legend-item p {
  margin: 0;
  color: var(--text-3);
  font-size: 12px;
}

.energy-analysis-legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
