  white-space: nowrap;
}

.energy-analysis-empty-inline {
  padding: 16px 0;
  color: var(--text-3);
  text-align: center;
}

.energy-efficiency-page {
  --energy-mode-accent: 99, 230, 255;
  --energy-mode-accent-soft: 0.12;
  --energy-mode-accent-strong: 0.24;
  display: grid;
  gap: 12px;
}

.energy-efficiency-page[data-tab="calendar"] {
  --energy-mode-accent: 99, 230, 255;
}

.energy-efficiency-page[data-tab="search"] {
  --energy-mode-accent: 79, 217, 184;
}

.energy-efficiency-page[data-tab="compare"] {
  --energy-mode-accent: 111, 167, 255;
}

.energy-efficiency-page[data-tab="proportion"] {
  --energy-mode-accent: 255, 210, 139;
}

.energy-efficiency-page[data-tab="imbalance"] {
  --energy-mode-accent: 255, 140, 198;
}

.energy-efficiency-header {
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(300px, 0.88fr);
  gap: 12px;
  align-items: start;
}

.energy-efficiency-command-copy {
  gap: 10px;
}

.energy-efficiency-eyebrow {
  margin: 0;
  color: rgba(133, 211, 255, 0.78);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.energy-efficiency-header h2 {
  margin: 0;
  font-size: 28px;
}

.energy-efficiency-header p {
  margin: 8px 0 0;
  max-width: 920px;
  color: var(--text-2);
  line-height: 1.7;
}

.energy-efficiency-command-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.energy-efficiency-command-tags span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid rgba(var(--energy-mode-accent), 0.18);
  background:
    linear-gradient(180deg, rgba(18, 40, 64, 0.62), rgba(10, 21, 36, 0.58)),
    radial-gradient(circle at top left, rgba(var(--energy-mode-accent), 0.16), transparent 62%);
  color: var(--text-2);
  backdrop-filter: blur(10px);
}

.energy-efficiency-command-tags strong {
  color: rgba(191, 222, 244, 0.72);
  font-size: 11px;
  font-weight: 600;
}

.energy-efficiency-command-tags em {
  color: var(--text-1);
  font-style: normal;
  font-size: 12px;
}

.energy-efficiency-header-status {
  display: grid;
  gap: 9px;
  padding: 14px 15px;
  border-radius: 20px;
  border: 1px solid rgba(var(--energy-mode-accent), 0.2);
  background:
    linear-gradient(180deg, rgba(18, 34, 48, 0.92), rgba(12, 22, 32, 0.88)),
    radial-gradient(circle at top left, rgba(var(--energy-mode-accent), 0.12), transparent 48%);
}

.energy-efficiency-header-status > span {
  color: var(--text-3);
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.energy-efficiency-header-status > strong {
  color: var(--text-1);
  font-size: 18px;
  line-height: 1.1;
}

.energy-efficiency-header-status > p {
  margin: 0;
  color: var(--text-2);
  font-size: 12px;
  line-height: 1.55;
}

.energy-efficiency-status-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.energy-efficiency-status-chip {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid rgba(var(--energy-mode-accent), 0.14);
  background: rgba(8, 24, 39, 0.44);
  color: rgba(194, 219, 238, 0.82);
  font-size: 11px;
  line-height: 1.35;
}

.energy-efficiency-header-status-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.energy-efficiency-command-stat {
  display: grid;
  gap: 5px;
  padding: 10px 11px;
  border-radius: 14px;
  border: 1px solid rgba(var(--energy-mode-accent), 0.1);
  background: rgba(8, 24, 39, 0.42);
}

.energy-efficiency-command-stat span {
  color: rgba(185, 213, 234, 0.7);
  font-size: 11px;
  letter-spacing: 0.02em;
}

.energy-efficiency-command-stat strong {
  color: var(--text-1);
  font-size: 14px;
  line-height: 1.35;
  word-break: break-word;
}

.energy-efficiency-command-stat small {
  color: var(--text-3);
  font-size: 11px;
  line-height: 1.45;
}

.energy-efficiency-tabs {
  display: flex;
  flex-wrap: nowrap;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 2px;
  scrollbar-width: none;
}

.energy-efficiency-tabs::-webkit-scrollbar {
  display: none;
}

.energy-efficiency-tabs button {
  flex: 0 0 auto;
  min-height: 40px;
  padding: 0 16px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-2);
  cursor: pointer;
}

.energy-efficiency-tabs button.active,
.energy-efficiency-tabs button.is-active,
.energy-efficiency-tabs button[aria-pressed="true"] {
  color: var(--text-1);
  border-color: rgba(var(--energy-mode-accent), 0.32);
  background: linear-gradient(135deg, rgba(var(--energy-mode-accent), 0.22), rgba(var(--energy-mode-accent), 0.1));
}

.energy-efficiency-filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  align-items: end;
}

.energy-efficiency-filter-grid.search-grid {
  grid-template-columns: minmax(280px, 1.4fr) repeat(3, minmax(0, 0.78fr));
}

.energy-efficiency-filter-grid.compare-grid {
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
}

.energy-efficiency-filter-grid.proportion-grid {
  grid-template-columns: minmax(250px, 1fr) minmax(170px, 0.68fr) minmax(96px, auto) minmax(96px, auto);
  align-items: end;
}

.energy-efficiency-filter-grid.calendar-grid {
  grid-template-columns: minmax(0, 240px) minmax(0, 280px);
}

.energy-efficiency-field {
  display: grid;
  gap: 7px;
  padding: 11px 12px 12px;
  border-radius: 16px;
  border: 1px solid rgba(var(--energy-mode-accent), 0.08);
  background:
    linear-gradient(180deg, rgba(12, 27, 43, 0.72), rgba(8, 18, 31, 0.68)),
    radial-gradient(circle at top left, rgba(var(--energy-mode-accent), 0.05), transparent 58%);
}

.energy-efficiency-field span {
  color: var(--text-3);
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.energy-efficiency-field input,
.energy-efficiency-field select {
  min-height: 40px;
  padding: 0 10px;
  border-radius: 12px;
  border: 1px solid rgba(115, 184, 246, 0.16);
  background:
    linear-gradient(180deg, rgba(7, 18, 30, 0.84), rgba(5, 13, 23, 0.82)),
    radial-gradient(circle at top left, rgba(var(--energy-mode-accent), 0.04), transparent 55%);
  color: var(--text-1);
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.energy-efficiency-field input:focus,
.energy-efficiency-field select:focus {
  outline: none;
  border-color: rgba(var(--energy-mode-accent), 0.34);
  box-shadow:
    0 0 0 3px rgba(var(--energy-mode-accent), 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  transform: translateY(-1px);
}

.energy-efficiency-field select[multiple] {
  min-height: 112px;
  padding: 8px 10px;
}

.energy-efficiency-device-check-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(112px, 1fr));
  gap: 8px;
}

.energy-efficiency-device-check-grid-single {
  grid-template-columns: repeat(auto-fit, minmax(118px, 1fr));
}

.energy-efficiency-device-check {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  border-radius: 12px;
  border: 1px solid rgba(115, 184, 246, 0.14);
  background:
    linear-gradient(180deg, rgba(7, 18, 30, 0.82), rgba(5, 13, 23, 0.78)),
    radial-gradient(circle at top left, rgba(var(--energy-mode-accent), 0.05), transparent 58%);
  color: var(--text-2);
  cursor: pointer;
  user-select: none;
  transition:
    border-color 160ms ease,
    background 160ms ease,
    color 160ms ease,
    box-shadow 160ms ease;
}

.energy-efficiency-device-check:hover {
  color: var(--text-1);
  border-color: rgba(var(--energy-mode-accent), 0.26);
  background:
    linear-gradient(180deg, rgba(11, 31, 50, 0.88), rgba(7, 20, 34, 0.82)),
    radial-gradient(circle at top left, rgba(var(--energy-mode-accent), 0.1), transparent 60%);
}

.energy-efficiency-device-check.is-checked {
  color: var(--text-1);
  border-color: rgba(var(--energy-mode-accent), 0.38);
  background:
    linear-gradient(135deg, rgba(var(--energy-mode-accent), 0.2), rgba(var(--energy-mode-accent), 0.08)),
    rgba(6, 17, 29, 0.84);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.energy-efficiency-device-check input {
  width: 14px;
  height: 14px;
  margin: 0;
  accent-color: rgb(var(--energy-mode-accent));
  cursor: pointer;
}

.energy-efficiency-device-check em {
  font-style: normal;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.03em;
  white-space: nowrap;
}

.energy-efficiency-inline-input {
  display: flex;
  align-items: center;
  gap: 8px;
}

.energy-efficiency-inline-input input {
  flex: 1;
  min-width: 0;
}

.energy-efficiency-field-stacked {
  height: 100%;
}

.energy-efficiency-compare-picker {
  display: grid;
  gap: 8px;
  align-content: start;
}

.energy-efficiency-compare-selection {
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
  max-height: 144px;
  overflow-y: auto;
}

.energy-efficiency-chip-list-compact {
  gap: 6px;
}

.energy-efficiency-filter-grid.compare-grid .energy-efficiency-button.compact {
  flex: none;
  min-width: 88px;
}

.energy-efficiency-toggle {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.energy-efficiency-toggle button {
  min-height: 38px;
  padding: 0 12px;
  border-radius: 10px;
  border: 1px solid var(--line-soft);
  background: rgba(7, 19, 30, 0.7);
  color: var(--text-2);
  cursor: pointer;
}

.energy-efficiency-toggle button.active {
  color: var(--text-1);
  border-color: rgba(143, 247, 215, 0.28);
  background: linear-gradient(135deg, rgba(79, 217, 184, 0.18), rgba(99, 230, 255, 0.12));
}

.energy-efficiency-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.energy-efficiency-button {
  min-width: 112px;
  min-height: 36px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-1);
  cursor: pointer;
}

.energy-efficiency-button.is-primary {
  border-color: rgba(143, 247, 215, 0.3);
  background: linear-gradient(135deg, rgba(79, 217, 184, 0.22), rgba(99, 230, 255, 0.16));
}

.energy-efficiency-proportion-action-button {
  align-self: end;
  min-width: 96px;
  min-height: 40px;
  margin-bottom: 0;
}

.energy-efficiency-button.compact {
  min-width: 88px;
}

.energy-efficiency-summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.energy-efficiency-summary-grid .stat-card.is-dense {
  min-height: 74px;
  padding: 10px 11px 8px;
  border-radius: 14px;
}

.energy-efficiency-summary-grid .stat-card.is-dense::after {
  left: 14px;
  right: 14px;
}

.energy-efficiency-summary-grid .stat-card.is-dense .stat-title {
  margin-bottom: 4px;
  font-size: 11px;
  letter-spacing: 0.02em;
}

.energy-efficiency-summary-grid .stat-card.is-dense .stat-main {
  gap: 5px;
  margin-bottom: 0;
}

.energy-efficiency-summary-grid .stat-card.is-dense .stat-main strong {
  font-size: clamp(16px, 1.5vw, 20px);
  line-height: 1.02;
}

.energy-efficiency-summary-grid .stat-card.is-dense .stat-main span {
  font-size: 10px;
}

.energy-efficiency-summary-grid .stat-card.is-dense .status-pill {
  display: none;
}

.energy-efficiency-top-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.22fr) minmax(280px, 0.78fr);
  gap: 14px;
  align-items: start;
}

.energy-efficiency-top-grid > .section-card:first-child {
  order: 2;
}

.energy-efficiency-top-grid > .section-card:last-child {
  order: 1;
}

.energy-efficiency-mode-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(320px, 0.88fr);
  gap: 12px;
  align-items: start;
  padding: 14px 16px;
  border-radius: 20px;
  border: 1px solid rgba(var(--energy-mode-accent), 0.18);
  background:
    linear-gradient(180deg, rgba(14, 25, 37, 0.94), rgba(10, 18, 28, 0.92)),
    radial-gradient(circle at top left, rgba(var(--energy-mode-accent), 0.1), transparent 56%);
}

.energy-efficiency-mode-hero.is-without-insight {
