}

.energy-efficiency-mode-hero.is-without-insight .energy-efficiency-strategy-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.energy-efficiency-mode-insight {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px 14px;
  align-items: center;
  padding: 0 0 2px;
}

