  border-color: rgba(255, 195, 97, 0.22);
}

.energy-efficiency-mode-insight-copy {
  display: grid;
  gap: 4px;
}

.energy-efficiency-mode-insight-copy span {
  color: var(--text-3);
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.energy-efficiency-mode-insight-copy strong {
  color: var(--text-1);
  font-size: 15px;
  line-height: 1.42;
  font-weight: 600;
}

.energy-efficiency-mode-insight-chips {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 6px;
}

.energy-efficiency-mode-insight-chips span {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid rgba(var(--energy-mode-accent), 0.18);
  background: rgba(10, 22, 34, 0.56);
  color: var(--text-2);
  font-size: 12px;
  white-space: nowrap;
}

.energy-efficiency-strategy-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.energy-efficiency-strategy-card {
  display: grid;
  gap: 6px;
  padding: 11px 12px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.025);
}

.energy-efficiency-strategy-card.is-featured {
  grid-column: 1 / -1;
  padding: 13px 14px;
