    radial-gradient(circle at top left, rgba(var(--energy-mode-accent), 0.12), transparent 52%);
}

.energy-efficiency-strategy-card.tone-good {
  border-color: rgba(143, 247, 215, 0.2);
}

.energy-efficiency-strategy-card.tone-warn {
  border-color: rgba(255, 210, 139, 0.22);
}

.energy-efficiency-strategy-card span {
  color: var(--text-3);
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.energy-efficiency-strategy-card strong {
  color: var(--text-1);
  font-size: 15px;
}

.energy-efficiency-strategy-card p {
  margin: 0;
  color: var(--text-2);
  line-height: 1.6;
}

.energy-efficiency-section-tip {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 8px;
  border-radius: 999px;
  border: 1px solid rgba(var(--energy-mode-accent), 0.16);
  background: rgba(9, 19, 30, 0.62);
  color: var(--text-3);
  font-size: 12px;
  line-height: 1.45;
}

.energy-efficiency-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 10px;
  margin-bottom: 10px;
  color: var(--text-3);
  font-size: 12px;
}

.energy-efficiency-calendar-title-meta {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin: 0;
  min-width: 0;
}

.energy-efficiency-calendar-title-meta span {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid rgba(var(--energy-mode-accent), 0.16);
  background: rgba(9, 19, 30, 0.58);
  color: var(--text-3);
  font-size: 12px;
  line-height: 1.35;
  white-space: nowrap;
}

.energy-efficiency-page .section-action:has(.energy-efficiency-calendar-title-meta) {
