.energy-efficiency-page .energy-efficiency-calendar-title-meta {
  flex: 1 1 auto;
}

.energy-efficiency-calendar-title-meta .energy-efficiency-calendar-title-guide {
  border-color: rgba(120, 216, 255, 0.22);
  background:
