.energy-efficiency-legend-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.03);
}

.energy-efficiency-legend-item strong {
  display: block;
  margin-bottom: 3px;
}

.energy-efficiency-legend-item p {
  margin: 0;
  color: var(--text-3);
  font-size: 12px;
}

.energy-efficiency-legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex: none;
