*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  min-height: 100%;
}

html {
  background: var(--bg-0);
}

body {
  margin: 0;
  position: relative;
  font-family: var(--font-ui);
  font-size: var(--font-size-body);
  line-height: 1.6;
  color: var(--text-1);
  background:
    radial-gradient(circle at 14% 8%, rgba(103, 220, 255, 0.14), transparent 30%),
    radial-gradient(circle at 84% 10%, rgba(109, 161, 255, 0.12), transparent 28%),
    radial-gradient(circle at 52% 100%, rgba(61, 109, 163, 0.24), transparent 42%),
    linear-gradient(180deg, var(--bg-0) 0%, var(--bg-1) 52%, #0d1f33 100%);
  letter-spacing: 0.01em;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body::before,
body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: -1;
}

body::before {
  background-image:
    linear-gradient(rgba(121, 198, 234, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(121, 198, 234, 0.04) 1px, transparent 1px);
  background-size: 72px 72px;
  mask-image: radial-gradient(circle at center, black 28%, transparent 80%);
  opacity: 0.9;
}

body::after {
  background:
    radial-gradient(circle at 50% 0%, rgba(180, 232, 255, 0.12), transparent 56%),
    radial-gradient(circle at 0% 100%, rgba(107, 169, 232, 0.1), transparent 44%),
    linear-gradient(180deg, rgba(103, 220, 255, 0.03), transparent 24%, rgba(103, 220, 255, 0.02) 72%, transparent 100%);
  filter: blur(28px);
}

a,
button,
input,
select {
  font-family: inherit;
}

button,
input,
select {
  outline: none;
}

button {
  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease,
    background 180ms ease,
    color 180ms ease,
    opacity 180ms ease;
}

button:hover {
  transform: translateY(-0.5px);
}

a {
  color: inherit;
}

:focus-visible {
  outline: 2px solid rgba(184, 216, 228, 0.52);
  outline-offset: 2px;
}

.page-enter {
  animation: fadeUp 420ms cubic-bezier(0.2, 0.72, 0.26, 1) both;
}

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(16px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes cardRise {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.985);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes shimmerMove {
  from {
    transform: translateX(-135%);
  }

  to {
    transform: translateX(140%);
  }
}

@keyframes techSweep {
  from {
    transform: translateX(-120%);
    opacity: 0;
  }

  20% {
    opacity: 0.34;
  }

  to {
    transform: translateX(135%);
    opacity: 0;
  }
}

@keyframes techPulse {
  0%,
  100% {
    opacity: 0.42;
  }

  50% {
    opacity: 0.82;
  }
}

