  box-shadow: 0 14px 32px rgba(3, 20, 38, 0.22);
}

.dashboard-quick-link span {
  position: relative;
  z-index: 1;
  color: var(--text-3);
  font-size: 12px;
  line-height: 1.5;
}

.dashboard-quick-link strong {
  position: relative;
  z-index: 1;
  font-size: 20px;
  line-height: 1.1;
}

.dashboard-quick-link small {
