  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: rgba(151, 223, 248, 0.92);
  font-size: 12px;
}

.dashboard-main-column,
.dashboard-side-column {
  display: grid;
  gap: 16px;
}

.dashboard-mini-kpis {
