  color: rgba(191, 214, 237, 0.78);
  font-size: 12px;
  line-height: 1.52;
}

.dashboard-command-loop {
  display: grid;
  gap: 12px;
  padding: 14px 0 2px;
}

.dashboard-command-loop-head {
