}

.dashboard-ops-status-note.tone-neutral {
  border-color: rgba(103, 220, 255, 0.22);
  background: rgba(13, 45, 74, 0.28);
}

.dashboard-ops-status-note strong {
  color: var(--text-1);
  font-size: 12px;
  line-height: 1.3;
}

.dashboard-ops-status-note small {
  color: var(--text-2);
  font-size: 11px;
  line-height: 1.45;
}

.dashboard-ops-rail-efficiency {
