.dashboard-efficiency-feature::after {
  content: "";
  position: absolute;
  inset: auto -8% -30% auto;
  width: 140px;
  height: 140px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(103, 220, 255, 0.1), rgba(103, 220, 255, 0));
  pointer-events: none;
}

.dashboard-efficiency-label-row,
.dashboard-efficiency-card-meta {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.dashboard-efficiency-feature > .dashboard-efficiency-label-row {
  width: 100%;
  justify-content: space-between;
  gap: 10px;
}

.dashboard-feature-band-note {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid rgba(103, 220, 255, 0.14);
  border-radius: 999px;
  background: rgba(14, 31, 48, 0.66);
  color: rgba(184, 205, 221, 0.78);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.03em;
  white-space: nowrap;
}

.dashboard-feature-band-note::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: rgba(103, 220, 255, 0.32);
  box-shadow: 0 0 10px rgba(103, 220, 255, 0.16);
}

.dashboard-feature-band-note.tone-good {
  border-color: rgba(112, 236, 191, 0.22);
  color: rgba(142, 243, 205, 0.92);
}

.dashboard-feature-band-note.tone-good::before {
  background: rgba(112, 236, 191, 0.86);
  box-shadow: 0 0 10px rgba(112, 236, 191, 0.22);
}

.dashboard-feature-band-note.tone-neutral {
  border-color: rgba(103, 220, 255, 0.18);
  color: rgba(197, 226, 244, 0.9);
}

.dashboard-feature-band-note.tone-neutral::before {
  background: rgba(103, 220, 255, 0.8);
}

.dashboard-feature-band-note.tone-warn {
  border-color: rgba(255, 196, 111, 0.22);
  color: rgba(255, 216, 153, 0.92);
}

.dashboard-feature-band-note.tone-warn::before {
  background: rgba(255, 196, 111, 0.86);
  box-shadow: 0 0 10px rgba(255, 196, 111, 0.2);
}

.dashboard-ops-card-action {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
  width: 100%;
}

.content.is-dashboard-content .dashboard-duty > .section-card:first-child > .section-card-header .section-action {
  flex: 1 1 840px;
  justify-content: flex-end;
}

.dashboard-ops-header-verdict {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex: 1 1 620px;
  flex-wrap: wrap;
  justify-content: flex-end;
  min-width: 0;
  max-width: none;
  min-height: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.dashboard-ops-header-verdict.tone-good {
  border-color: transparent;
  background: transparent;
}

.dashboard-ops-header-verdict.tone-warn {
  border-color: transparent;
  background: transparent;
}

.dashboard-ops-header-verdict-copy {
  display: inline-flex;
  align-items: center;
  flex: 1 1 360px;
  gap: 7px;
  min-width: 0;
  justify-content: flex-end;
}

.dashboard-ops-header-verdict-copy span {
  flex: 0 0 auto;
  color: rgba(174, 206, 226, 0.78);
  font-size: 11.5px;
  font-weight: 700;
  white-space: nowrap;
}

.dashboard-ops-header-verdict-copy strong {
  display: block;
  min-width: 0;
  max-width: none;
  overflow: visible;
  color: rgba(218, 237, 248, 0.9);
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
  text-overflow: clip;
  white-space: normal;
}

.dashboard-ops-header-meta {
  min-width: 0;
  gap: 5px;
  flex-wrap: wrap;
  justify-content: flex-end;
  white-space: normal;
}

.dashboard-ops-header-meta span {
  max-width: none;
  overflow: visible;
  text-overflow: clip;
}

.dashboard-ops-action-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 10px;
  border: 1px solid rgba(103, 220, 255, 0.14);
  border-radius: 999px;
  background: rgba(14, 31, 48, 0.48);
  color: rgba(185, 206, 223, 0.74);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.dashboard-ops-action-pill.is-info {
  color: #ccecff;
  border-color: rgba(114, 205, 255, 0.28);
  background: rgba(25, 82, 118, 0.22);
}

.dashboard-ops-action-pill.is-refresh-flash {
  animation: dashboard-refresh-chip 1.2s ease-out;
}

.dashboard-threshold-trigger {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 10px;
  border: 1px solid rgba(103, 220, 255, 0.14);
  border-radius: 999px;
  background: rgba(14, 31, 48, 0.48);
  color: rgba(185, 206, 223, 0.74);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.02em;
  cursor: help;
  user-select: none;
  white-space: nowrap;
  transition: border-color 160ms ease, color 160ms ease, background 160ms ease;
}

.dashboard-threshold-trigger::after {
  content: attr(data-tooltip);
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 80;
  display: none;
  width: max-content;
  max-width: min(420px, 72vw);
  padding: 10px 12px;
  border: 1px solid rgba(103, 220, 255, 0.2);
  background: rgba(8, 18, 30, 0.96);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.32);
  color: rgba(226, 241, 250, 0.94);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.7;
  letter-spacing: 0;
  text-align: left;
  white-space: pre-line;
  pointer-events: none;
}

.dashboard-threshold-trigger:hover,
.dashboard-threshold-trigger:focus-visible {
  outline: none;
  border-color: rgba(103, 220, 255, 0.22);
  background: rgba(18, 38, 57, 0.62);
  color: rgba(224, 237, 247, 0.88);
}

.dashboard-threshold-trigger:hover::after,
.dashboard-threshold-trigger:focus-visible::after {
  display: block;
}

.dashboard-efficiency-feature-body {
  display: grid;
  grid-template-columns: minmax(240px, 0.68fr) minmax(470px, 1.32fr);
  gap: 18px;
  align-items: stretch;
}

.dashboard-efficiency-feature-main {
  display: grid;
  min-height: 100%;
  gap: 8px;
  align-content: start;
}

.dashboard-efficiency-feature strong {
  margin-top: 0;
}

.dashboard-efficiency-feature-status {
  display: flex;
  align-items: flex-start;
  gap: 0;
}

.dashboard-feature-delta {
  display: inline-flex !important;
  align-items: center;
  min-height: 24px;
  padding: 0 8px;
  border: 1px solid rgba(103, 220, 255, 0.14);
  border-radius: 999px;
  background: rgba(16, 36, 54, 0.52);
  color: rgba(199, 218, 233, 0.82);
  font-size: 9px !important;
  font-weight: 600;
}

.dashboard-feature-delta.tone-good {
  border-color: rgba(112, 236, 191, 0.22);
  color: rgba(140, 243, 205, 0.94);
}

.dashboard-feature-delta.tone-warn {
  border-color: rgba(255, 196, 111, 0.24);
  color: rgba(255, 214, 146, 0.94);
}

.dashboard-efficiency-feature-trend {
  display: grid;
  gap: 0;
  align-content: stretch;
  justify-items: stretch;
  min-height: 156px;
}

.dashboard-efficiency-feature-trend-plot {
  position: relative;
  width: 100%;
  padding-top: 8px;
  padding-bottom: 18px;
  cursor: crosshair;
}

.dashboard-efficiency-feature-tooltip {
  position: absolute;
  z-index: 3;
  display: inline-flex !important;
  align-items: center;
  min-height: 20px;
  padding: 0 7px;
  border: 1px solid rgba(103, 220, 255, 0.16);
  border-radius: 999px;
  background: rgba(12, 28, 43, 0.88);
  color: rgba(210, 228, 240, 0.86) !important;
  font-size: 8.5px !important;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
  box-shadow: 0 10px 20px rgba(2, 10, 20, 0.18);
  transform: translate(-50%, -100%);
}

.dashboard-efficiency-feature-tooltip.is-left {
  transform: translate(0, -100%);
}

.dashboard-efficiency-feature-tooltip.is-right {
  transform: translate(-100%, -100%);
}

.dashboard-efficiency-feature-trend svg {
  width: 100%;
  height: 84px;
}

.dashboard-trend-gap {
  stroke: rgba(103, 220, 255, 0.18);
  stroke-width: 1.2;
  stroke-dasharray: 4 5;
}

.dashboard-efficiency-feature-axis {
  position: relative;
  height: 22px;
  margin-top: 4px;
}

.dashboard-efficiency-feature-axis::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, rgba(103, 220, 255, 0.08), rgba(103, 220, 255, 0.22), rgba(103, 220, 255, 0.08));
}

.dashboard-efficiency-feature-axis span {
  position: absolute;
  top: 0;
  color: rgba(166, 190, 208, 0.58) !important;
  font-size: 8.3px !important;
  line-height: 1;
  transform: translateX(-50%);
  white-space: nowrap;
}

.dashboard-efficiency-feature-axis span i {
  display: block;
  width: 1px;
  height: 6px;
  margin: 0 auto 5px;
  background: rgba(103, 220, 255, 0.26);
}

.dashboard-efficiency-feature-axis span bdi {
  display: block;
}

.dashboard-efficiency-feature-axis span:first-child {
  transform: none;
}

.dashboard-efficiency-feature-axis span:first-child i {
  margin-left: 0;
}

.dashboard-efficiency-feature-axis span:last-child {
  transform: translateX(-100%);
}

.dashboard-efficiency-feature-axis span:last-child i {
  margin-right: 0;
}

.dashboard-efficiency-feature-trend path {
  fill: none;
  stroke: rgba(103, 220, 255, 0.88);
  stroke-width: 2.1;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 10px rgba(103, 220, 255, 0.12));
}

.dashboard-efficiency-feature-trend small {
  color: rgba(183, 208, 226, 0.62) !important;
  font-size: 8.8px !important;
  text-align: right;
}

.dashboard-efficiency-caption {
  color: rgba(181, 202, 219, 0.7);
  line-height: 1.42;
}

.dashboard-efficiency-summary {
  margin: 0;
  max-width: 29ch;
  color: rgba(211, 226, 236, 0.9);
  font-size: 11.5px;
  line-height: 1.52;
}

.dashboard-metric-value {
  display: inline-flex !important;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 6px;
}

.dashboard-metric-main {
  display: inline-block;
}

.dashboard-metric-unit {
  display: inline-block;
  margin-bottom: 0.12em;
  color: rgba(211, 230, 244, 0.82);
  font-size: 0.58em;
  font-style: normal;
  letter-spacing: 0.01em;
}

.dashboard-efficiency-decomposition {
  display: grid;
  gap: 8px;
  align-content: start;
}

.dashboard-efficiency-decomposition-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 12px;
  padding: 0 4px;
}

.dashboard-efficiency-decomposition-head span {
  color: rgba(188, 211, 228, 0.7);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.dashboard-efficiency-decomposition-head small {
  color: rgba(162, 186, 205, 0.62);
  font-size: 10px;
  line-height: 1.4;
