  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
  padding: 8px;
  border: 1px solid rgba(103, 220, 255, 0.14);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(14, 30, 47, 0.72), rgba(11, 22, 34, 0.8)),
    radial-gradient(circle at top left, rgba(103, 220, 255, 0.06), transparent 40%);
