  position: relative;
}

.dashboard-efficiency-chain::before {
  content: "";
  position: absolute;
  left: 18px;
  right: 18px;
  top: 56px;
  height: 1px;
  background: none;
  transform: translateY(-50%);
  box-shadow: 0 0 14px rgba(103, 220, 255, 0.1);
  pointer-events: none;
}

.dashboard-efficiency-chain-card {
  position: relative;
  min-height: 104px;
  padding: 10px 10px 10px;
  gap: 5px;
  align-content: start;
  background:
    linear-gradient(180deg, rgba(12, 24, 38, 0.78), rgba(10, 20, 31, 0.84)),
    radial-gradient(circle at top left, rgba(103, 220, 255, 0.04), transparent 42%);
}

.dashboard-efficiency-chain-card::before {
  content: "";
