  height: 8px;
  flex: 0 0 auto;
  border-radius: 999px;
  box-shadow: 0 0 10px currentColor;
}

.report-record-chart-plot-frame {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr);
