  align-items: stretch;
  min-width: 0;
  overflow: visible;
}

.report-record-chart-y-axis {
  position: relative;
  height: 292px;
  color: rgba(181, 211, 231, 0.76);
  font-size: 12px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}

.report-record-chart-y-axis span {
  position: absolute;
  right: 0;
  max-width: 56px;
  overflow: hidden;
  text-align: right;
  text-overflow: ellipsis;
  transform: translateY(-50%);
  white-space: nowrap;
}

.report-record-chart-plot {
  position: relative;
  height: 292px;
  min-width: 0;
  overflow: visible;
  border-radius: 18px;
