  background:
    linear-gradient(180deg, rgba(4, 15, 27, 0.64), rgba(4, 12, 23, 0.72)),
    repeating-linear-gradient(90deg, rgba(109, 191, 255, 0.04) 0 1px, transparent 1px 72px);
  cursor: crosshair;
}

.report-record-chart-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.report-record-chart-grid-line {
  stroke: rgba(130, 196, 231, 0.14);
  stroke-width: 0.35;
  vector-effect: non-scaling-stroke;
}

.report-record-chart-hover-line {
  stroke: rgba(218, 246, 255, 0.46);
  stroke-width: 0.45;
  stroke-dasharray: 2 3;
  vector-effect: non-scaling-stroke;
}

.report-record-chart-tooltip {
  position: absolute;
  top: 14px;
  z-index: 30;
  display: grid;
  gap: 6px;
  min-width: min(420px, calc(100vw - 96px));
  max-width: min(520px, calc(100vw - 96px));
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid rgba(117, 216, 255, 0.2);
  background: rgba(5, 16, 28, 0.94);
  box-shadow: 0 18px 34px rgba(0, 0, 0, 0.28);
  transform: translateX(10px);
  pointer-events: none;
  backdrop-filter: blur(12px);
}

.report-record-chart-tooltip.is-left {
  transform: translateX(calc(-100% - 10px));
}

.report-record-chart-tooltip.is-two-column {
  min-width: min(620px, calc(100vw - 96px));
  max-width: min(620px, calc(100vw - 96px));
  grid-template-columns: repeat(2, minmax(220px, 1fr));
  column-gap: 14px;
  row-gap: 7px;
}

.report-record-chart-tooltip.is-two-column strong {
  grid-column: 1 / -1;
}

.report-record-chart-tooltip.is-two-column span {
  min-width: 0;
}

.report-record-chart-tooltip strong {
  color: var(--text-1);
  font-size: 12px;
}

.report-record-chart-tooltip span {
  display: grid;
  grid-template-columns: 8px minmax(180px, 1fr) max-content;
  justify-content: space-between;
  color: rgba(198, 224, 240, 0.86);
  font-size: 12px;
}

.report-record-chart-tooltip em {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-style: normal;
}

.report-record-chart-tooltip b {
  color: var(--text-1);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.report-record-chart-axis {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-left: 66px;
  color: rgba(181, 211, 231, 0.72);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.report-record-chart-axis span {
  max-width: 32%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.report-record-chart-empty {
  display: grid;
  min-height: 160px;
  place-items: center;
  color: rgba(190, 218, 236, 0.78);
  font-size: 13px;
  text-align: center;
}

.report-record-table-shell {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.03),
    0 20px 36px rgba(4, 12, 21, 0.18);
}

.report-record-table thead th:first-child,
.report-record-table tbody td:first-child {
  position: sticky;
  left: 0;
}

.report-record-table thead th:first-child {
  z-index: 2;
  background: rgba(10, 31, 54, 0.98);
}

.report-record-table tbody td:first-child {
  color: var(--text-1);
  background: rgba(8, 24, 42, 0.94);
  font-variant-numeric: tabular-nums;
}

.report-record-table tbody tr:nth-child(even) td {
  background: rgba(10, 25, 40, 0.54);
}

.report-record-table tbody tr:nth-child(even) td:first-child {
  background: rgba(9, 27, 45, 0.96);
}

.report-record-table tbody td {
  font-variant-numeric: tabular-nums;
}

.report-record-pagination {
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid rgba(109, 191, 255, 0.1);
}

@media (max-width: 1180px) {
  .report-record-filter-layout {
    grid-template-columns: 1fr;
  }

  .report-record-command-side-grid,
  .report-record-filter-panel-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 860px) {
  .report-record-command-tags,
  .report-record-table-stage-meta,
  .report-record-selected-regs {
    gap: 6px;
  }

  .report-record-command-tags span,
  .report-record-table-stage-meta span,
  .report-record-selected-reg {
    min-height: 32px;
    padding-inline: 10px;
  }

  .report-record-command-side-grid,
  .report-record-filter-panel-grid {
    grid-template-columns: 1fr;
  }

  .report-record-table-stage {
    flex-direction: column;
  }
}

