/* App shell mobile navigation */
.mobile-nav-toggle,
.nav-close-button,
.nav-overlay {
  display: none;
}

.mobile-nav-toggle {
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: 4px;
  width: 40px;
  height: 40px;
  padding: 0;
  border-radius: 14px;
  border: 1px solid rgba(103, 220, 255, 0.14);
  background:
    linear-gradient(180deg, rgba(17, 31, 47, 0.92), rgba(10, 20, 32, 0.88)),
    radial-gradient(circle at top left, rgba(103, 220, 255, 0.1), transparent 58%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    0 8px 18px rgba(5, 16, 27, 0.18);
}

.mobile-nav-toggle-line {
  display: block;
  width: 16px;
  height: 1.5px;
  border-radius: 999px;
  background: rgba(231, 242, 252, 0.92);
}

.nav-close-button {
  position: absolute;
  top: 12px;
  right: 12px;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border-radius: 12px;
  border: 1px solid rgba(103, 220, 255, 0.12);
  background: rgba(6, 18, 29, 0.66);
  color: rgba(232, 241, 248, 0.88);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.nav-overlay {
  position: fixed;
  inset: 0;
  z-index: 29;
  padding: 0;
  border: 0;
  background: rgba(4, 10, 18, 0.46);
  backdrop-filter: blur(5px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 180ms ease;
}

@media (max-width: 900px) {
  .app-shell {
    position: relative;
    grid-template-columns: minmax(0, 1fr);
    min-height: 100svh;
    overflow-x: clip;
  }

  .app-shell[data-mobile-nav-open="true"] {
    height: 100svh;
    overflow: hidden;
  }

  .app-shell > main {
    grid-column: 1 / -1;
    width: 100%;
    min-width: 0;
    height: 100svh;
    min-height: 100svh;
    background: linear-gradient(180deg, rgba(7, 14, 23, 0.88), rgba(6, 12, 20, 0.84));
  }

  .left-nav {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: min(82vw, 320px);
    height: 100svh;
    padding: calc(16px + env(safe-area-inset-top, 0px)) 12px calc(18px + env(safe-area-inset-bottom, 0px));
    border-right: 1px solid rgba(103, 220, 255, 0.12);
    border-bottom: 0;
    z-index: 40;
    overflow: hidden;
    box-shadow: 22px 0 48px rgba(2, 7, 14, 0.46);
    transform: translateX(calc(-100% - 18px));
    opacity: 0;
    pointer-events: none;
    transition:
      transform 220ms ease,
      opacity 180ms ease,
      box-shadow 220ms ease;
  }

  .app-shell[data-mobile-nav-open="true"] .left-nav {
    transform: translateX(0);
    opacity: 1;
    pointer-events: auto;
  }

  .nav-brand {
    padding-right: 48px;
  }

  .nav-scroll {
    padding-right: 0;
  }

  .mobile-nav-toggle,
  .nav-close-button,
  .nav-overlay {
    display: inline-flex;
  }

  .app-shell[data-mobile-nav-open="true"] .nav-overlay {
    opacity: 1;
    pointer-events: auto;
  }

  .top-bar {
    position: sticky;
    top: 0;
    z-index: 20;
    min-height: 60px;
    padding: 0 14px;
  }

  .top-left {
    gap: 12px;
  }

  .top-right {
    min-width: 0;
  }
}

@media (max-width: 640px) {
  .top-bar {
    padding: calc(12px + env(safe-area-inset-top, 0px)) 14px 14px;
    gap: 10px;
  }

  .top-left {
    align-items: flex-start;
  }

  .top-heading {
    gap: 3px;
  }

  .top-heading span {
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
  }

  .top-system-meta {
