/* Scene control: remote 2D/3D iframe shell */
.scene-embed-page {
  display: grid;
  width: 100%;
  height: calc(100vh - 58px);
  min-height: 0;
  overflow: hidden;
  scrollbar-color: rgba(104, 190, 255, 0.34) transparent;
}

.scene-embed-page::-webkit-scrollbar,
.scene-embed-shell::-webkit-scrollbar,
.scene-embed-stage::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

.scene-embed-page::-webkit-scrollbar-track,
.scene-embed-page::-webkit-scrollbar-track-piece,
.scene-embed-page::-webkit-scrollbar-corner,
.scene-embed-shell::-webkit-scrollbar-track,
.scene-embed-shell::-webkit-scrollbar-track-piece,
.scene-embed-shell::-webkit-scrollbar-corner,
.scene-embed-stage::-webkit-scrollbar-track,
.scene-embed-stage::-webkit-scrollbar-track-piece,
.scene-embed-stage::-webkit-scrollbar-corner {
  background: transparent;
}

.scene-embed-page::-webkit-scrollbar-thumb,
.scene-embed-shell::-webkit-scrollbar-thumb,
.scene-embed-stage::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: rgba(104, 190, 255, 0.34);
  background-clip: padding-box;
}

.scene-embed-shell {
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  overflow: hidden;
  width: 100%;
  height: 100%;
  max-width: 100%;
  min-height: 100%;
  border: 0;
  border-radius: 0;
  background: #06131f;
  box-shadow: none;
  scrollbar-color: rgba(104, 190, 255, 0.34) transparent;
}

.scene-embed-shell:fullscreen {
  width: 100vw;
  height: 100vh;
  background: #06131f;
}

.scene-embed-shell:fullscreen .scene-embed-frame {
  min-height: 0;
}

.scene-embed-runtimebar {
  position: relative;
  z-index: 5;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: stretch;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid rgba(112, 201, 255, 0.18);
  background:
    linear-gradient(180deg, rgba(10, 26, 43, 0.96), rgba(6, 18, 31, 0.94));
  box-shadow: inset 0 -1px 0 rgba(255, 255, 255, 0.03);
  pointer-events: auto;
}

.scene-embed-runtime-grid {
  display: grid;
  grid-template-columns: minmax(166px, 1.14fr) repeat(5, minmax(118px, 1fr));
  gap: 8px;
  min-width: 0;
}

.scene-embed-shell.is-runtime-collapsed .scene-embed-runtime-grid {
  grid-template-columns: repeat(4, minmax(126px, 1fr));
}

.scene-embed-runtime-card {
  display: grid;
  align-content: start;
  min-width: 0;
  min-height: 76px;
  padding: 10px 11px;
  border: 1px solid rgba(112, 201, 255, 0.16);
  border-radius: 8px;
  background: rgba(7, 24, 40, 0.7);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.055);
}

.scene-embed-runtime-card.is-primary {
  border-color: rgba(94, 231, 151, 0.38);
  background:
    linear-gradient(135deg, rgba(94, 231, 151, 0.14), rgba(7, 24, 40, 0.72) 62%);
}

.scene-embed-runtime-card-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  min-width: 0;
  gap: 8px;
}

.scene-embed-runtime-card-head span,
.scene-embed-runtime-card-head em {
  overflow: hidden;
  color: rgba(179, 212, 236, 0.78);
  font-size: 11px;
  line-height: 15px;
  min-height: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scene-embed-runtime-card-head em {
  flex: 0 0 auto;
  color: rgba(218, 235, 247, 0.9);
  font-style: italic;
}

.scene-embed-runtime-card strong {
  display: flex;
  align-items: baseline;
  overflow: hidden;
  gap: 6px;
  margin-top: 7px;
  color: #f5fbff;
  font-size: 22px;
  line-height: 30px;
  min-height: 30px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scene-embed-runtime-card.is-primary strong {
