  font-size: 11px;
  font-weight: 700;
}

.scene-embed-runtime-card p {
  overflow: hidden;
  margin: 7px 0 0;
  color: rgba(183, 213, 236, 0.74);
  font-size: 11px;
  line-height: 15px;
  min-height: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scene-embed-shell.is-runtime-collapsed .scene-embed-runtimebar {
  padding-block: 8px;
}

.scene-embed-shell.is-runtime-collapsed .scene-embed-runtime-card {
  min-height: 58px;
  padding: 8px 10px;
}

.scene-embed-shell.is-runtime-collapsed .scene-embed-runtime-card strong,
.scene-embed-shell.is-runtime-collapsed .scene-embed-runtime-card.is-primary strong {
  margin-top: 5px;
  font-size: 20px;
}

.scene-embed-shell.is-runtime-collapsed .scene-embed-runtime-card p {
  margin-top: 5px;
}

.scene-embed-runtime-side {
  display: grid;
  align-content: stretch;
  min-width: 118px;
  gap: 6px;
}

.scene-embed-runtime-source,
.scene-embed-runtime-alarm,
.scene-embed-runtime-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
