  border: 1px solid rgba(112, 201, 255, 0.18);
  border-radius: 8px;
  background: rgba(8, 28, 46, 0.58);
  color: rgba(213, 232, 247, 0.9);
  font-size: 11px;
  line-height: 1.2;
  text-align: center;
  white-space: nowrap;
}

.scene-embed-runtime-source,
.scene-embed-runtime-alarm {
  overflow: hidden;
  min-width: 0;
  text-overflow: ellipsis;
}

.scene-embed-runtime-source.is-good {
  border-color: rgba(94, 231, 151, 0.28);
  background: rgba(11, 45, 34, 0.5);
  color: rgba(221, 255, 239, 0.94);
}

.scene-embed-runtime-source.is-warn,
.scene-embed-runtime-alarm.is-danger {
  border-color: rgba(255, 185, 98, 0.34);
  background: rgba(70, 43, 14, 0.54);
  color: rgba(255, 229, 188, 0.96);
}

.scene-embed-runtime-toggle {
  min-height: 30px;
  border-color: rgba(106, 194, 255, 0.28);
  background: rgba(24, 79, 118, 0.72);
  color: #eef9ff;
  cursor: pointer;
  font-family: "Microsoft YaHei", "PingFang SC", "Noto Sans SC", sans-serif;
  font-size: 12px;
  font-weight: 700;
}

.scene-embed-runtimebar .scene-embed-runtime-toggle {
  font-size: 12px;
}

.scene-embed-runtime-toggle:hover {
  border-color: rgba(111, 211, 255, 0.5);
  background: rgba(38, 113, 158, 0.86);
}

.scene-embed-stage {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: #06131f;
  scrollbar-color: rgba(104, 190, 255, 0.34) transparent;
}

.scene-embed-stage.is-fit-native {
  overflow: hidden;
}

.scene-embed-frame {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 0;
  border: 0;
  background: #06131f;
  overflow: hidden;
  transform-origin: center center;
  transform: none;
  will-change: auto;
}

.scene-embed-frame.is-fit-native {
  width: var(--scene-native-width, 2500px);
  height: var(--scene-native-height, 920px);
  min-width: var(--scene-native-width, 2500px);
  min-height: var(--scene-native-height, 920px);
  overflow: hidden;
  transform: translate(var(--scene-native-x, 0), var(--scene-native-y, 0)) scale(var(--scene-native-scale, 1));
  transform-origin: left top;
  will-change: transform;
}

.scene-embed-frame.is-fit-zoom {
  transform: scale(1.12);
  will-change: transform;
}

.scene-embed-frame.is-prewarm {
  position: absolute;
  top: 0;
  left: -10000px;
  width: var(--scene-native-width, 2500px) !important;
  height: var(--scene-native-height, 920px) !important;
  min-width: var(--scene-native-width, 2500px) !important;
  min-height: var(--scene-native-height, 920px) !important;
  opacity: 0;
  visibility: visible;
  pointer-events: none;
  transform: none !important;
  will-change: auto;
}

.scene-embed-loading-layer {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: grid;
  place-items: center;
  pointer-events: none;
  background:
    radial-gradient(circle at center, rgba(13, 42, 58, 0.82) 0, rgba(6, 19, 31, 0.62) 38%, rgba(3, 10, 17, 0.34) 72%),
    linear-gradient(180deg, rgba(6, 18, 30, 0.12), rgba(6, 18, 30, 0.38));
}

.scene-embed-loading-card {
  display: grid;
  justify-items: center;
  gap: 8px;
  min-width: 188px;
  padding: 18px 22px 16px;
  border: 1px solid rgba(116, 211, 255, 0.18);
  border-radius: 8px;
  background: rgba(7, 22, 36, 0.76);
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(10px);
}

.scene-embed-loading-mark {
  position: relative;
  width: 48px;
  height: 48px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(113, 238, 182, 0.18) 0 30%, rgba(113, 238, 182, 0) 32%);
}

.scene-embed-loading-mark::before,
.scene-embed-loading-mark::after {
  position: absolute;
  content: "";
  border-radius: inherit;
}

.scene-embed-loading-mark::before {
  inset: 0;
  background: conic-gradient(from 0deg, rgba(111, 211, 255, 0.1), rgba(111, 211, 255, 0.92), rgba(115, 232, 162, 0.78), rgba(111, 211, 255, 0.1));
  mask: radial-gradient(circle, transparent 55%, #000 57%);
  animation: scene-loading-ring 1.45s linear infinite;
}

.scene-embed-loading-mark::after {
  inset: 15px;
  background: rgba(117, 233, 181, 0.92);
  box-shadow: 0 0 22px rgba(117, 233, 181, 0.4);
  animation: scene-loading-breathe 1.8s ease-in-out infinite;
}

.scene-embed-loading-card strong {
  color: #f4fbff;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0;
}

.scene-embed-loading-card > span:not(.scene-embed-loading-mark) {
  color: rgba(202, 224, 238, 0.76);
  font-size: 12px;
  font-weight: 600;
}

.scene-embed-loading-meter {
  display: grid;
  grid-template-columns: repeat(3, 18px);
  gap: 5px;
  margin-top: 3px;
}

.scene-embed-loading-meter i {
  display: block;
  height: 3px;
  border-radius: 999px;
  background: rgba(111, 211, 255, 0.28);
  animation: scene-loading-meter 1.2s ease-in-out infinite;
}

.scene-embed-loading-meter i:nth-child(2) {
  animation-delay: 0.14s;
}

.scene-embed-loading-meter i:nth-child(3) {
  animation-delay: 0.28s;
}

@keyframes scene-loading-ring {
  to {
    transform: rotate(360deg);
  }
}

@keyframes scene-loading-breathe {
  0%,
  100% {
    transform: scale(0.86);
    opacity: 0.72;
  }
  50% {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes scene-loading-meter {
  0%,
  100% {
    background: rgba(111, 211, 255, 0.2);
  }
  50% {
    background: rgba(117, 233, 181, 0.86);
  }
}

@media (prefers-reduced-motion: reduce) {
  .scene-embed-loading-mark::before,
  .scene-embed-loading-mark::after,
  .scene-embed-loading-meter i {
    animation: none;
  }
}

.scene-embed-empty {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 10px;
  min-height: 100%;
  padding: 28px;
  text-align: center;
