.scene-embed-switchbar {
  position: relative;
  z-index: 5;
  display: grid;
  grid-template-columns: minmax(132px, 0.72fr) minmax(300px, 1fr) auto;
  align-items: center;
  justify-content: space-between;
  width: 100%;
