    min-height: calc(100vh - 58px);
  }

  .scene-embed-runtimebar {
    grid-template-columns: 1fr;
    padding: 8px;
  }

  .scene-embed-runtime-grid,
  .scene-embed-shell.is-runtime-collapsed .scene-embed-runtime-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

