    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .scene-embed-toolbar {
    display: grid;
    grid-template-columns: 1fr;
    justify-content: stretch;
  }

  .scene-embed-fit-actions {
