/* Apple Material fidelity pass: align the live dashboard with the accepted
   concept while preserving the current engineering data layout. */
:root {
  --material-bg-top: #091523;
  --material-bg-mid: #10243a;
  --material-bg-bottom: #07121f;
  --material-panel: linear-gradient(180deg, rgba(25, 45, 66, 0.78), rgba(10, 23, 36, 0.76));
  --material-card: linear-gradient(180deg, rgba(20, 39, 58, 0.72), rgba(10, 24, 38, 0.72));
  --material-card-soft: linear-gradient(180deg, rgba(22, 43, 64, 0.64), rgba(9, 22, 35, 0.66));
  --material-warn: linear-gradient(180deg, rgba(67, 50, 27, 0.62), rgba(23, 25, 29, 0.78));
  --material-line: rgba(142, 198, 236, 0.18);
  --material-line-strong: rgba(142, 198, 236, 0.3);
  --material-radius-panel: 12px;
  --material-radius-card: 10px;
  --material-shadow-panel: 0 22px 58px rgba(0, 8, 18, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.045);
  --material-shadow-card: inset 0 1px 0 rgba(255, 255, 255, 0.04), 0 10px 28px rgba(0, 10, 22, 0.14);
}

