}

.meter-reading-compact-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  height: 36px;
  min-height: 36px;
  padding: 0 10px;
  border-bottom: 1px solid rgba(107, 191, 230, 0.12);
}

.meter-reading-compact-panel-head h3 {
  margin: 0;
  color: #f5fcff;
  font-size: 14px;
  font-weight: 780;
  line-height: 1;
}

.meter-reading-compact-panel-body {
  flex: 1;
  min-height: 0;
  padding: 10px;
  overflow: hidden;
}

.meter-reading-compact-workspace > .meter-reading-compact-panel:last-child .meter-reading-compact-panel-body {
