  flex-direction: column;
  padding: 8px;
}

.meter-reading-compact-form-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}

.meter-reading-compact-field {
  display: grid;
  gap: 5px;
  margin: 0;
}

.meter-reading-compact-field span {
  color: #8eb4c8;
  font-size: 11px;
  font-weight: 760;
  line-height: 1;
}

.meter-reading-compact-field input {
  width: 100%;
  height: 34px;
  min-width: 0;
  padding: 0 10px;
  border: 1px solid rgba(111, 194, 235, 0.24);
  border-radius: 8px;
