}

.meter-reading-compact-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  margin-top: 10px;
}

.meter-reading-compact-button {
  display: grid;
  place-items: center;
  height: 32px;
  min-width: 0;
  padding: 0 8px;
  border: 1px solid rgba(111, 194, 235, 0.28);
  border-radius: 999px;
  color: #dceff8;
  background: rgba(13, 35, 54, 0.86);
  font-size: 12px;
  font-weight: 760;
  line-height: 1;
}

.meter-reading-compact-button.is-primary {
  color: #f8fdff;
  border-color: rgba(88, 211, 255, 0.56);
  background: linear-gradient(180deg, rgba(68, 154, 194, 0.85), rgba(33, 91, 125, 0.86));
}

.meter-reading-compact-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.meter-reading-compact-inline-error {
  margin-top: 8px;
  padding: 7px 8px;
  border: 1px solid rgba(255, 107, 117, 0.26);
  border-radius: 8px;
  color: #ffadb4;
  background: rgba(62, 18, 25, 0.42);
  font-size: 11px;
  font-weight: 720;
}

.meter-reading-compact-source-list {
  display: grid;
  gap: 7px;
  margin-top: 10px;
}

.meter-reading-compact-source-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  min-height: 46px;
  padding: 8px;
  border: 1px solid rgba(107, 191, 230, 0.12);
  border-radius: 8px;
  background: rgba(5, 18, 29, 0.78);
}

.meter-reading-compact-source-row strong {
  display: block;
  color: #f0fbff;
  font-size: 12px;
  font-weight: 780;
