}

.meter-reading-compact-source-row small {
  display: block;
  margin-top: 5px;
}

.meter-reading-compact-source-row > span {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 10px;
  border-radius: 999px;
  color: #ffd166;
  background: rgba(255, 209, 102, 0.12);
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;
}

.meter-reading-compact-source-row > span.is-ok {
  color: #72f0b4;
  background: rgba(61, 207, 149, 0.13);
}

.meter-reading-compact-table-panel .meter-reading-compact-panel-body {
  padding: 0;
}

.meter-reading-compact-table-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  height: 34px;
  padding: 0 10px;
  border-bottom: 1px solid rgba(107, 191, 230, 0.12);
  color: #8fb0c1;
  font-size: 11px;
  font-weight: 760;
}

.meter-reading-compact-table-meta span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.meter-reading-compact-table-wrap {
  height: calc(100% - 34px);
  min-height: 0;
  overflow: auto;
}

.meter-reading-compact-table {
  width: 100%;
  min-width: 0;
  table-layout: fixed;
  border-collapse: collapse;
}

.meter-reading-compact-table th,
.meter-reading-compact-table td {
  height: 31px;
  padding: 0 5px;
  border-bottom: 1px solid rgba(132, 202, 232, 0.1);
  text-align: left;
  vertical-align: middle;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.meter-reading-compact-table th {
  color: #9bc0d1;
  background: rgba(14, 45, 62, 0.98);
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}

.meter-reading-compact-table td {
  color: #effbff;
  font-size: 11px;
  font-weight: 670;
  line-height: 1;
}

.meter-reading-compact-table td.is-highlight {
  color: #72f0b4;
  font-weight: 800;
}

.meter-reading-compact-table td.is-time {
  color: #f4fbff;
  font-weight: 780;
}

.meter-reading-compact-empty {
  display: grid;
  place-items: center;
  height: 100%;
  color: #8fb0c1;
  font-size: 12px;
  font-weight: 720;
}

.meter-reading-compact-mini-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
}

.meter-reading-compact-mini-grid article {
  min-height: 45px;
  padding: 7px;
  border: 1px solid rgba(107, 191, 230, 0.12);
  border-radius: 8px;
  background: rgba(5, 18, 29, 0.78);
}

.meter-reading-compact-mini-grid strong {
  display: block;
  margin-top: 5px;
  color: #f5fcff;
  font-size: 16px;
  font-weight: 780;
  line-height: 1;
}

.meter-reading-compact-field-list {
  flex: 1;
  min-height: 0;
  height: auto;
  margin-top: 7px;
  overflow: auto;
  border: 1px solid rgba(107, 191, 230, 0.12);
  border-radius: 8px;
  background: rgba(5, 18, 29, 0.72);
}

.meter-reading-compact-field-list div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 6px;
  align-items: center;
  min-height: 26px;
  padding: 0 7px;
  border-bottom: 1px solid rgba(132, 202, 232, 0.08);
}

.meter-reading-compact-field-list div:last-child {
  border-bottom: 0;
}

.meter-reading-compact-field-list strong {
  color: #e7f6fc;
  font-size: 11px;
  font-weight: 700;
}

.meter-reading-compact-boundary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
  min-width: 0;
}

.meter-reading-compact-boundary article {
  display: grid;
  gap: 5px;
  height: 42px;
  padding: 6px 9px;
  overflow: hidden;
}

.meter-reading-compact-boundary strong {
  color: #f4fbff;
  font-size: 12px;
  font-weight: 780;
  line-height: 1;
}

@media (max-width: 1180px) {
  .meter-reading-compact-page-v2 {
    height: auto;
    min-height: 0;
    overflow: visible;
  }

  .meter-reading-compact-workspace {
    grid-template-columns: 1fr;
    overflow: visible;
  }

  .meter-reading-compact-table-wrap {
    min-height: 320px;
    overflow-x: auto;
  }

  .meter-reading-compact-table {
    min-width: 820px;
  }
}

@media (max-width: 760px) {
  .meter-reading-compact-page-v2 {
    grid-template-rows: auto;
  }

  .meter-reading-compact-hero,
  .meter-reading-compact-tags,
  .meter-reading-compact-metrics,
  .meter-reading-compact-boundary {
    grid-template-columns: 1fr;
  }

  .meter-reading-compact-hero {
    overflow: visible;
  }

  .meter-reading-compact-hero-copy {
    display: grid;
    grid-template-columns: 1fr;
    grid-template-rows: auto;
    row-gap: 7px;
  }

  .meter-reading-compact-hero h2,
  .meter-reading-compact-tags {
    grid-column: auto;
    grid-row: auto;
  }

  .meter-reading-compact-status {
    margin: 0 10px 10px;
  }

  .meter-reading-compact-metric,
  .meter-reading-compact-boundary article {
    height: auto;
    min-height: 58px;
  }

  .meter-reading-compact-table-meta {
    align-items: flex-start;
    flex-direction: column;
    height: auto;
    padding: 8px 10px;
  }
}

