  .energy-parameter-compact-page-v2 {
    grid-template-rows: auto;
  }

  .energy-parameter-compact-hero,
  .energy-parameter-compact-hero-copy,
  .energy-parameter-compact-tags,
  .energy-parameter-compact-metrics,
  .energy-parameter-compact-workspace,
  .energy-parameter-compact-period-grid,
  .energy-parameter-compact-boundary {
    grid-template-columns: 1fr;
  }

