  }

  .energy-parameter-compact-status {
    margin: 0 10px 10px;
  }

  .energy-parameter-compact-metric,
  .energy-parameter-compact-boundary article {
    height: auto;
    min-height: 58px;
  }

  .energy-parameter-compact-date-row,
  .energy-parameter-compact-actions,
  .energy-parameter-compact-audit-grid {
    grid-template-columns: 1fr;
