/* AI overview board: executable concept version for owner-facing demo review. */
.content.is-subpage-compact:has(> .ai-overview-page) {
  --content-pad-y: 12px;
  --content-pad-x: 12px;
  padding-bottom: 12px;
  background:
    linear-gradient(90deg, rgba(90, 215, 255, 0.04) 1px, transparent 1px) 0 0 / 72px 72px,
    linear-gradient(0deg, rgba(90, 215, 255, 0.035) 1px, transparent 1px) 0 0 / 72px 72px,
    radial-gradient(circle at 70% 18%, rgba(112, 246, 174, 0.1), transparent 28%),
    linear-gradient(145deg, #06131d 0%, #071a28 52%, #06111b 100%);
}

.ai-overview-page {
  --ai-bg: #06131d;
  --ai-panel: rgba(12, 32, 47, 0.93);
  --ai-panel-strong: rgba(10, 40, 56, 0.8);
  --ai-line: rgba(90, 169, 211, 0.32);
  --ai-text: #edf8ff;
  --ai-muted: #9eb4c6;
  --ai-subtle: #6f879b;
  --ai-cyan: #5ad7ff;
  --ai-green: #70f6ae;
  --ai-amber: #ffca6b;
  --ai-red: #ff6b74;
  display: grid;
  grid-template-rows: 56px 88px minmax(0, 1fr) 124px;
  gap: 8px;
  height: calc(100dvh - 150px);
  min-height: 704px;
  overflow: hidden;
  color: var(--ai-text);
  font-family: var(--font-ui);
}

.ai-overview-page * {
  box-sizing: border-box;
}

.ai-overview-header,
.ai-kpi-card,
.ai-plant-panel,
.ai-rec-panel,
.ai-chart-card,
.ai-safety-panel {
  border: 1px solid var(--ai-line);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(14, 38, 56, 0.94), rgba(9, 29, 43, 0.9));
  box-shadow: 0 18px 34px rgba(0, 0, 0, 0.28);
}

.ai-overview-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-width: 0;
  padding: 10px 14px;
}

.ai-overview-kicker {
  display: block;
  color: var(--ai-cyan);
  font-size: 12px;
  font-weight: 800;
  line-height: 16px;
}

.ai-overview-header h2 {
  margin: 3px 0 0;
  color: var(--ai-text);
  font-size: clamp(24px, 2.2vw, 32px);
  line-height: 1.08;
  font-weight: 900;
}

.ai-overview-mode-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
  min-width: 390px;
}

.ai-mode-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  padding: 0 11px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  background: rgba(7, 24, 36, 0.82);
  color: var(--ai-muted);
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

.ai-mode-chip.good {
  border-color: rgba(112, 246, 174, 0.32);
  background: rgba(28, 88, 65, 0.22);
  color: var(--ai-green);
}

.ai-mode-chip.warn {
  border-color: rgba(255, 202, 107, 0.34);
  background: rgba(120, 80, 28, 0.22);
  color: var(--ai-amber);
}

.ai-mode-chip.info {
  border-color: rgba(90, 215, 255, 0.32);
  background: rgba(34, 90, 110, 0.22);
  color: var(--ai-cyan);
}

.ai-kpi-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

.ai-kpi-card {
  position: relative;
  min-width: 0;
  overflow: hidden;
  padding: 9px 16px;
}

.ai-kpi-card::after {
  content: "";
  position: absolute;
  display: none;
  left: 16px;
  right: 16px;
  bottom: 4px;
  height: 3px;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--ai-green), rgba(90, 215, 255, 0.72), rgba(255, 202, 107, 0.26));
}

.ai-card-label,
.ai-equipment-head,
.ai-panel-title,
.ai-rec-main span {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
