  gap: 1px 7px;
  min-width: 0;
  min-height: 0;
  padding: 5px 8px;
  background: rgba(112, 246, 174, 0.07);
  border-color: rgba(112, 246, 174, 0.2);
}

.ai-safety-grid svg {
  grid-row: 1 / 3;
  align-self: center;
  color: var(--ai-green);
}

.ai-safety-grid b {
  min-width: 0;
  overflow: hidden;
  color: var(--ai-green);
  font-size: 10.5px;
  line-height: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ai-safety-grid small {
  min-width: 0;
  overflow: hidden;
  color: var(--ai-muted);
  font-size: 9px;
  line-height: 11px;
