@media (max-width: 1180px) {
  .ai-overview-page {
    grid-template-rows: auto auto auto auto;
    height: auto;
    min-height: 0;
    overflow: visible;
  }

  .ai-overview-header,
  .ai-overview-main,
  .ai-bottom-grid {
    grid-template-columns: 1fr;
  }

  .ai-overview-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .ai-overview-mode-row {
    justify-content: flex-start;
    min-width: 0;
  }

  .ai-kpi-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ai-plant-network {
    height: 520px;
  }

  .ai-rec-panel,
  .ai-chart-card,
  .ai-safety-panel {
    min-height: 220px;
  }
}

@media (max-width: 760px) {
  .content.is-subpage-compact:has(> .ai-overview-page) {
    --content-pad-y: 8px;
    --content-pad-x: 8px;
  }

  .ai-kpi-strip,
  .ai-rec-metrics,
  .ai-safety-grid {
    grid-template-columns: 1fr;
  }

  .ai-plant-network {
    display: grid;
    height: auto;
    min-height: 0;
    gap: 8px;
  }

  .ai-flow,
  .ai-water-pill {
    display: none;
  }

  .ai-equipment-card {
    position: static;
    width: 100%;
  }
}

/* Secondary navigation active state: keep the current card entry visually unambiguous after click. */
html body #root .secondary-nav-link {
  position: relative !important;
  overflow: hidden !important;
}

html body #root .secondary-nav-link.active,
html body #root .secondary-nav-link.is-current,
html body #root .secondary-nav-link[aria-current="page"] {
  border-color: rgba(103, 185, 238, 0.56) !important;
  background:
    linear-gradient(180deg, rgba(54, 105, 145, 0.74), rgba(31, 70, 103, 0.72)),
    rgba(18, 60, 92, 0.72) !important;
  color: rgba(245, 251, 255, 0.98) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    0 0 0 1px rgba(103, 185, 238, 0.12),
    0 8px 20px rgba(0, 12, 26, 0.22),
    0 0 18px rgba(103, 185, 238, 0.12) !important;
}

html body #root .secondary-nav-link.active::before,
html body #root .secondary-nav-link.is-current::before,
html body #root .secondary-nav-link[aria-current="page"]::before {
  content: "";
  position: absolute;
  inset: 5px auto 5px 5px;
  width: 2px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(124, 210, 255, 0.96), rgba(104, 218, 163, 0.72));
  box-shadow: 0 0 10px rgba(124, 210, 255, 0.58);
}

html body #root .secondary-nav-link.active svg,
html body #root .secondary-nav-link.active span,
html body #root .secondary-nav-link.is-current svg,
html body #root .secondary-nav-link.is-current span,
html body #root .secondary-nav-link[aria-current="page"] svg,
html body #root .secondary-nav-link[aria-current="page"] span {
  position: relative;
  z-index: 1;
  color: rgba(245, 251, 255, 0.98) !important;
  text-shadow: 0 1px 10px rgba(0, 17, 22, 0.42);
}

html body #root .secondary-nav-link.active svg,
html body #root .secondary-nav-link.is-current svg,
html body #root .secondary-nav-link[aria-current="page"] svg {
  color: rgba(220, 242, 255, 0.98) !important;
}

